// ConvertEasy service worker. Generated by scripts/build.mjs, do not edit dist/sw.js.
//
// Scope is the root of converteasy.lowkey.tools. Other apps use separate
// origins; cleanup still only deletes caches carrying our own prefix.
//
// - Hashed assets (/assets/*): cache first, they never change.
// - Pages: network first with a short timeout, then cache, then the right
//   tool page for that URL (from pages.json), then home. Every converter works
//   offline even on pages never visited.
// - Other same-origin files: stale while revalidate.
// - Cross-origin requests (exchange rates) are not intercepted.

const VERSION = '__VERSION__';
const PREFIX = 'converteasy-';
const CACHE = `${PREFIX}${VERSION}`;
const PRECACHE = __PRECACHE__;
const TOOL_PATHS = __TOOL_PATHS__;
const NAV_TIMEOUT = 3500;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE.map((u) => new Request(u, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== CACHE).map((k) => caches.delete(k)));
      if (self.registration.navigationPreload) await self.registration.navigationPreload.enable();
      await self.clients.claim();
    })(),
  );
});

function inScope(url) {
  return url.origin === self.location.origin;
}

function normalize(pathname) {
  const p = pathname.replace(/\/+$/, '').replace(/\.html$/, '');
  return p === '/index' ? '/' : p || '/';
}

async function fallbackFor(pathname) {
  const cache = await caches.open(CACHE);
  try {
    const res = await cache.match(`/pages.json`);
    if (res) {
      const pages = await res.json();
      const rel = pathname === '/' ? '' : pathname;
      const page = pages.find((p) => p.p === rel);
      const target = page && TOOL_PATHS[page.x];
      if (target) {
        const hit = await cache.match(target);
        if (hit) return hit;
      }
    }
  } catch {
    /* fall through to home */
  }
  return (await cache.match('/')) ?? new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
}

async function handleNavigation(event, url) {
  const cache = await caches.open(CACHE);
  const key = normalize(url.pathname);
  try {
    const preload = event.preloadResponse ? await event.preloadResponse : null;
    const network =
      preload ??
      (await Promise.race([
        fetch(event.request),
        new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), NAV_TIMEOUT)),
      ]));
    if (network && network.ok && network.type === 'basic') cache.put(key, network.clone());
    return network;
  } catch {
    return (await cache.match(key)) ?? fallbackFor(key);
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (!inScope(url)) return;

  if (request.mode === 'navigate') {
    event.respondWith(handleNavigation(event, url));
    return;
  }

  if (url.pathname.startsWith(`/assets/`)) {
    event.respondWith(
      caches.open(CACHE).then(async (cache) => {
        const hit = await cache.match(request);
        if (hit) return hit;
        const res = await fetch(request);
        if (res.ok) cache.put(request, res.clone());
        return res;
      }),
    );
    return;
  }

  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const hit = await cache.match(request, { ignoreSearch: true });
      const refresh = fetch(request)
        .then((res) => {
          if (res.ok && res.type === 'basic') cache.put(request, res.clone());
          return res;
        })
        .catch(() => hit);
      return hit ?? refresh;
    }),
  );
});
